import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Text-to-speech: chat feature, not a connector","description":"","frontmatter":{"id":7,"title":"Text-to-speech: chat feature, not a connector","status":"decided","date":"August 2026","author":"Claude Code (session with the developer)","scope":"shared","summary":"Candidate capability — read assistant chat responses aloud, fully offline","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/research/0007-text-to-speech.md"},"headers":[],"relativePath":"sovereign-edge/research/0007-text-to-speech.md","filePath":"sovereign-edge/research/0007-text-to-speech.md"}'),i={name:"sovereign-edge/research/0007-text-to-speech.md"};function s(r,e,c,l,h,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="research-0007-—-text-to-speech-chat-feature-not-a-connector" tabindex="-1">Research 0007 — Text-to-speech: chat feature, not a connector <a class="header-anchor" href="#research-0007-—-text-to-speech-chat-feature-not-a-connector" aria-label="Permalink to &quot;Research 0007 — Text-to-speech: chat feature, not a connector&quot;">​</a></h1><p><strong>Related:</strong> <a href="./../epics/mobile/core-inference-chat.html">Core Inference &amp; Chat epic</a>, <a href="./0006-files-document-summarization.html">research 0006</a> (the same connector-vs-feature question, same conclusion)</p><hr><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>Should &quot;read chat responses aloud&quot; be built as a Tier 1 connector (per the proposal&#39;s original &quot;Device connector&quot; framing), and what does the offline TTS pipeline actually require?</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><ul><li>Same trust-boundary reasoning as <a href="./0006-files-document-summarization.html">0006</a>, more clearly so: TTS never leaves the device and never touches anything the user hasn&#39;t already put on their own screen. There is no permission boundary for epic 2&#39;s connector machinery to gate here at all.</li><li><code>expo-speech</code> (<code>Speech.speak()</code>) drives each OS&#39;s built-in on-device engine — <code>AVSpeechSynthesizer</code> on iOS, Android&#39;s <code>TextToSpeech</code> service. Fully offline on both platforms, using whatever system voices are already installed. This is meaningfully different from LLM-driven speech synthesis: voice quality and selection are whatever the OS ships, not something this app generates or controls beyond rate/pitch/voice choice.</li><li>No new runtime permission is needed for basic playback on either platform. (Speech <em>recognition</em> — microphone input, turning voice into text — is an unrelated, separate capability this doc does not cover.)</li><li>Scope is genuinely small: a speak/stop control on assistant message bubbles, calling <code>Speech.speak(message.text)</code>. The real decisions are product/UX, not technical: <ul><li>What happens if a new message arrives while one is being read aloud — queue, interrupt, or ignore?</li><li>Does playback continue if the app is backgrounded? iOS requires a background-audio capability/entitlement to keep playing after backgrounding — a real scope decision (and a capability addition to the Xcode project), not just a code change.</li><li>Voice/rate/pitch: exposed as a setting, or OS defaults only for MVP?</li></ul></li></ul><h2 id="options-considered" tabindex="-1">Options considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options considered&quot;">​</a></h2><p><strong>A. Route through the Connector Framework as a &quot;Device connector&quot; capability.</strong> Rejected — no trust boundary is crossed; would misuse the permission-grant machinery for something that needs none.</p><p><strong>B. Plain chat-screen feature: a speak/stop control per message, using <code>expo-speech</code> directly.</strong> Recommended.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Option B. This is the cheapest, least architecturally entangled item across the whole capability survey — no new epic under Connector Framework, just a small addition to the existing Chat screen (task 8.1) or Core Inference &amp; Chat epic.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><ul><li>Not a connector. No manifest entry, no permission grant, no in-chat provenance UI — none of epic 2&#39;s machinery applies.</li><li>Foreground-only playback for MVP; background-continuing audio is a separate, explicit scope decision (and an iOS capability addition) to make later if wanted.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Voice/rate/pitch: settings-exposed or OS defaults only for MVP?</li><li>Behavior when a new message arrives mid-speech.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Small task under whichever epic ends up owning it (Core Inference &amp; Chat or Mobile App Shell) — no new epic file needed, and no research blocker before scheduling it.</p>',18)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
